SELECT CASE WHEN event_type IN ('search', 'click') THEN 'priority' ELSE 'other' END AS event_type_group, event_type, MAX(duration_sec) AS max_duration_sec, COUNT(DISTINCT duration_sec) AS unique_sessions FROM web_events WHERE TO_DATE(event_time) < '2023-05-24' GROUP BY event_type_group, event_type HAVING COUNT(DISTINCT duration_sec) < 3 ORDER BY event_type_group ASC, event_type ASC LIMIT 50;
